      if(stopLossPrice <= 0)
      {
         Print("Failed to calculate a valid Stop Loss price. Aborting trade.");
         return;
      }

      // Get the current Ask price for the buy order
      double price = SymbolInfoDouble(symbol, SYMBOL_ASK);

      // Check if calculated SL is too close to the market price (broker requirement)
      int stops_level = (int)SymbolInfoInteger(symbol, SYMBOL_TRADE_STOPS_LEVEL);
      if(stops_level > 0)
      {
         double min_sl_distance = stops_level * _Point;
         if(orderType == ORDER_TYPE_BUY && (price - stopLossPrice < min_sl_distance))
         {
             Print("Calculated SL ", stopLossPrice, " is too close to the current price ", price, ". Minimum distance is ", min_sl_distance);
             // Optional: Adjust SL to the minimum allowed distance
             // stopLossPrice = price - min_sl_distance;
             // Print("Adjusted SL to minimum allowed: ", stopLossPrice);
             return; // Or abort
         }
      }

      //--- Open the BUY position with the calculated stop loss
