      //--- Check the result
      if(trade.ResultRetcode() == TRADE_RETCODE_DONE)
      {
         Print("Buy order opened successfully. Result: ", trade.ResultRetcode());
      }
      else
      {
         Print("Failed to open buy order. Result: ", trade.ResultRetcode(), ", Error: ", GetLastError());
      }
   }
